CREATE TABLE IF NOT EXISTS "apikey" (
  "id" text NOT NULL PRIMARY KEY, "configId" text NOT NULL, "name" text, "start" text, "referenceId" text NOT NULL, "prefix" text, "key" text NOT NULL, "refillInterval" integer, "refillAmount" integer, "lastRefillAt" date, "enabled" integer, "rateLimitEnabled" integer, "rateLimitTimeWindow" integer, "rateLimitMax" integer, "requestCount" integer, "remaining" integer, "lastRequest" date, "expiresAt" date, "createdAt" date NOT NULL, "updatedAt" date NOT NULL, "permissions" text, "metadata" text
);
CREATE INDEX IF NOT EXISTS "apikey_configId_idx" ON "apikey" ("configId");
CREATE INDEX IF NOT EXISTS "apikey_referenceId_idx" ON "apikey" ("referenceId");
CREATE INDEX IF NOT EXISTS "apikey_key_idx" ON "apikey" ("key");

CREATE TABLE rm_workspace_service_principals (
  user_id TEXT PRIMARY KEY REFERENCES "user"(id),
  display_name TEXT NOT NULL CHECK(length(trim(display_name)) BETWEEN 1 AND 120),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE rm_workspace_service_principal_events (
  id INTEGER PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES rm_workspace_service_principals(user_id),
  credential_id TEXT,
  event_type TEXT NOT NULL CHECK(event_type IN ('created','credential_issued','credential_rotated','credential_revoked')),
  actor TEXT NOT NULL CHECK(length(trim(actor)) BETWEEN 3 AND 160),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK((event_type='created' AND credential_id IS NULL) OR (event_type IN ('credential_issued','credential_rotated','credential_revoked') AND length(trim(credential_id)) > 0))
);
CREATE INDEX rm_workspace_service_principal_events_user_idx ON rm_workspace_service_principal_events(user_id,id DESC);
CREATE TRIGGER rm_workspace_service_principals_no_update BEFORE UPDATE ON rm_workspace_service_principals BEGIN SELECT RAISE(ABORT, 'workspace service principals are immutable'); END;
CREATE TRIGGER rm_workspace_service_principals_no_delete BEFORE DELETE ON rm_workspace_service_principals BEGIN SELECT RAISE(ABORT, 'workspace service principals are immutable'); END;
CREATE TRIGGER rm_workspace_service_principal_events_no_update BEFORE UPDATE ON rm_workspace_service_principal_events BEGIN SELECT RAISE(ABORT, 'workspace service principal events are append-only'); END;
CREATE TRIGGER rm_workspace_service_principal_events_no_delete BEFORE DELETE ON rm_workspace_service_principal_events BEGIN SELECT RAISE(ABORT, 'workspace service principal events are append-only'); END;
